test('V17.6.9 broker deployment: a missing AZURE_CREDENTIALS (or any required key) BLOCKS the deployment with an explicit, actionable annotation — names only, no value, no bypass of Azure authentication', () => {
  const db = src('.github/workflows/deploy-broker.yml'); const pre = db.slice(db.indexOf('- name: Preflight'), db.indexOf('- name: Verify the PAT')); assert.ok(pre.length > 500);
  for (const k of ['SQLA_BROKER_APP_NAME', 'AZURE_CREDENTIALS', 'SQLA_GITHUB_PAT', 'SQLA_GITHUB_CLIENT_ID', 'SQLA_ALLOWED_ORIGINS']) assert.match(pre, new RegExp(`need (secret|variable)\\s+${k} `), k);
  assert.match(pre, /Deployment blocked: \$2 is not configured\. Stage: preflight\. Component: repository access service/); assert.match(pre, /Retry: not retryable until it is set/); assert.match(pre, /docs\/DEPLOYMENT\.md/); assert.match(pre, /exit 1/);
  assert.ok(!/echo[^\n]*\$\{?(PAT|AZURE)\b|printf[^\n]*\$\{?(PAT|AZURE)\b|set -x/.test(pre), 'no secret value is printed'); assert.ok(db.indexOf('- name: Preflight') < db.indexOf('azure/login@v2'), 'the preflight precedes the Azure login, which is never bypassed'); assert.match(db, /azure\/login@v2\s*\n\s+with: \{ creds: '\$\{\{ secrets\.AZURE_CREDENTIALS \}\}' \}/);
  const script = pre.slice(pre.indexOf('run: |') + 6).split('\n').map((l) => l.replace(/^ {10}/, '')).join('\n'); const out = spawnSync('bash', ['-c', script], { encoding: 'utf8', env: { PATH: process.env.PATH, PAT: 'ghp_' + 'Z'.repeat(36), CLIENT: 'Iv1.abc', ORIGINS: 'https://x.example.org', APP: 'app', AZURE: '', GITHUB_STEP_SUMMARY: join(tmpdir(), 'sqla-summary.md') } });
  assert.equal(out.status, 1); assert.match(out.stdout, /::error title=Deployment blocked - AZURE_CREDENTIALS is not configured::Deployment blocked: AZURE_CREDENTIALS is not configured\./); assert.ok(!out.stdout.includes('ghp_') && !out.stderr.includes('ghp_'), 'the PAT value is never printed'); assert.ok(!/SQLA_GITHUB_PAT is not configured/.test(out.stdout), 'only what is missing is reported');
  const ok = spawnSync('bash', ['-c', script], { encoding: 'utf8', env: { PATH: process.env.PATH, PAT: 'p', CLIENT: 'c', ORIGINS: 'o', APP: 'a', AZURE: '{"clientId":"x"}', GITHUB_STEP_SUMMARY: join(tmpdir(), 'sqla-summary2.md') } }); assert.equal(ok.status, 0); assert.ok(!ok.stdout.includes('clientId'));
});

