test('V17.6.9 broker deployment (V17.7.5: packaging only): the workflow that used to deliver the PAT to a cloud host is replaced by a credential-free packaging workflow — it reads no secret, deploys nothing, and a PAT present in the environment never reaches the artifact', () => {
  const db = src('.github/workflows/package-repo-broker.yml'); assert.ok(!/secrets\./.test(db), 'no secret'); assert.ok(!/azure|app-settings|webapps-deploy|need (secret|variable)/i.test(db), 'no cloud step, no preflight of secrets'); assert.match(db, /permissions: \{ contents: read \}/); assert.match(db, /node scripts\/package-service\.mjs broker --self-test/); assert.ok(!/echo[^\n]*(PAT|secrets\.)|set -x/.test(db), 'no secret value is printed');
  const out = mkdtempSync(join(tmpdir(), 'sqla-pk-')); const PAT = 'ghp_' + 'Z'.repeat(36); const SES = 'S'.repeat(40);
  try {
    const r = spawnSync(process.execPath, [join(root, 'scripts/package-service.mjs'), 'broker', '--out', out], { encoding: 'utf8', env: { PATH: process.env.PATH, SQLA_GITHUB_PAT: PAT, SQLA_SESSION_SECRET: SES } }); assert.equal(r.status, 0, r.stderr); const dir = join(out, 'sqla-repo-broker');
    for (const f of readdirSync(dir)) { const t = readFileSync(join(dir, f), 'utf8'); assert.ok(!t.includes(PAT) && !t.includes(SES), `${f}: the PAT / session secret of the environment never reaches the artifact`); } assert.ok(!r.stdout.includes('ghp_') && !r.stderr.includes('ghp_'), 'the PAT value is never printed');
    const env = readFileSync(join(dir, 'env.example'), 'utf8'); for (const k of ['SQLA_GITHUB_PAT', 'SQLA_SESSION_SECRET', 'SQLA_GITHUB_CLIENT_ID', 'SQLA_ALLOWED_ORIGINS']) assert.match(env, new RegExp(`^${k}=$`, 'm'), `${k} is documented by name, with no value`);
  } finally { rmSync(out, { recursive: true, force: true }); }
});
